499	            GmemTiledCopyQ{},
500	            mQ,
501	            SmemLayoutQ{},
502	            TileShape_MNK{},
503	            ClusterShape{}); // no mcast for Q
504	        Tensor mK = make_tensor(make_gmem_ptr(args.ptr_K), args.shape_K, args.stride_K);
505	        TMA_K tma_load_K = make_tma_copy_B_sm90(
506	            GmemTiledCopyKV{},
507	            mK,
508	            take<0, 2>(SmemLayoutK{}),
509	            TileShape_MNK{},
510	            ClusterShape{}); // mcast along M mode for this N load, if any
511	        Tensor mV = make_tensor(make_gmem_ptr(args.ptr_V),
512	                                make_shape(args.headdim_v, get<0>(args.shape_K), get<2>(args.shape_K), get<3>(args.shape_K)),
513	                                select<1, 0, 2, 3>(args.stride_V));
514	        TMA_V tma_load_V = make_tma_copy(
515	            GmemTiledCopyKV{},
516	            mV,
517	            take<0, 2>(SmemLayoutVt{}),
518	            select<1, 2>(TileShape_MNK_PV{}),
519	            size<0>(ClusterShape{})); // mcast along M mode for this N load, if any
520	        Tensor mKnew = make_tensor(make_gmem_ptr(args.ptr_K_new), args.shape_K_new, args.stride_K_new);
521	        TMA_K tma_load_K_new = make_tma_copy_B_sm90(
522	            GmemTiledCopyKV{},
523	            cute::conditional_return<AppendKV>(mKnew, mK),
524	            take<0, 2>(SmemLayoutK{}),
525	            TileShape_MNK{},
526	            ClusterShape{}); // mcast along M mode for this N load, if any
527	        Tensor mVnew = make_tensor(make_gmem_ptr(args.ptr_V_new),
528	                                   make_shape(args.headdim_v, get<0>(args.shape_K_new), get<2>(args.shape_K_new), get<3>(args.shape_K_new)),
529	                                   select<1, 0, 2, 3>(args.stride_V_new));
530	        TMA_V tma_load_V_new = make_tma_copy(
531	            GmemTiledCopyKV{},
532	            cute::conditional_return<AppendKV>(mVnew, mV),
533	            take<0, 2>(SmemLayoutVt{}),
534	            select<1, 2>(TileShape_MNK_PV{}),
535	            size<0>(ClusterShape{})); // mcast along M mode for this N load, if any
536	        auto shape_Qv = make_shape(get<0>(args.shape_Q), args.headdim_v, get<2>(args.shape_Q), get<3>(args.shape_Q));
537	        Tensor mQv = make_tensor(make_gmem_ptr(args.ptr_Qv), shape_Qv, args.stride_Qv);
538	        TMA_Qv tma_load_Qv = [&] {
539	            if constexpr (HasQv) {
540	                return make_tma_copy_A_sm90(
541	                    GmemTiledCopyQ{},
542	                    mQv,
543	                    SmemLayoutQv{},
544	                    TileShape_MNK_QV{},
545	                    ClusterShape{}); // no mcast for Qv
546	            } else {
547	                return nullptr;
548	            }
549	        }();
550	        
551	        auto const shape_Qv_packed = cute::conditional_return<!PackGQA>(
552	            shape_Qv,
553	            make_shape(make_shape(qhead_per_khead, get<0>(shape_Qv)), get<1>(shape_Qv), get<2>(args.shape_K), get<3>(shape_Qv))
554	        );
555	        auto const stride_Qv_packed = cute::conditional_return<!PackGQA>(
556	            args.stride_Qv,
557	            make_stride(make_stride(get<2>(args.stride_Qv), get<0>(args.stride_Qv)), get<1>(args.stride_Qv), get<2>(args.stride_Qv) * qhead_per_khead, get<3>(args.stride_Qv))
558	        );
559	        if (get<1>(args.shape_rotary) > 0) {
560	            assert(args.ptr_rotary_cos != nullptr && args.ptr_rotary_sin != nullptr);
561	        }
562	        assert(args.num_splits >= 1);
563	        int page_size = !args.ptr_pagetable ? 1 : get<0>(args.shape_K);
564	        if (!PagedKVNonTMA && args.ptr_pagetable != nullptr) {
565	            assert(page_size % kBlockN == 0);
566	            assert(!args.leftpad_k);
567	            assert(!Is_local); // Since we now use leftpad_k with local, we can't use TMA with PagedKV
568	        }
569	        // If there's tanh softcapping, we do tanh(scores * softmax_scale / softcap_val) * softcap_val.
570	        // Right after this, we multiply by log2(e) before applying exp2.
571	        // To reduce the number of instructions, we instead pre-multiply softmax_scale / softcap_val
572	        // (assigning it to params.softcap_val) and pre-multiply softcap_val * log2(e)
573	        // (assigning it to params.softmax_scale_log2).
574	        return {args.ptr_Q, args.shape_Q, args.stride_Q, shape_Q_packed, stride_Q_packed,
575	                args.ptr_K, args.shape_K, args.stride_K, args.ptr_V, args.headdim_v, args.stride_V,
576	                args.ptr_K_new, args.shape_K_new, args.stride_K_new, args.ptr_V_new, args.stride_V_new,
577	                args.ptr_Qv, args.stride_Qv, shape_Qv_packed, stride_Qv_packed,
578	                args.ptr_rotary_cos, args.shape_rotary, args.stride_rotary_cos,
579	                args.ptr_rotary_sin, args.stride_rotary_sin, args.is_rotary_interleaved,
580	                args.ptr_pagetable, args.shape_pagetable, args.stride_pagetable,
581	                cutlass::FastDivmod(page_size),  // page_size_divmod
582	                cutlass::FastDivmod(!args.ptr_pagetable ? 1 : cute::ceil_div(page_size, kBlockN)),  // blockN_per_page_size_divmod
583	                cutlass::FastDivmod(cute::ceil_div(get<2>(args.shape_Q), get<2>(args.shape_K))),
584	                tma_load_Q, tma_load_K, tma_load_V, tma_load_K_new, tma_load_V_new, tma_load_Qv,
585	                !Has_softcap ? float(args.softmax_scale * M_LOG2E) : float(args.softcap_val * M_LOG2E),
586	                args.ptr_q_descale, args.ptr_k_descale, args.ptr_v_descale,
587	                args.stride_q_descale, args.stride_k_descale, args.stride_v_descale,
588	                !Has_softcap ? 0.f : args.softmax_scale / args.softcap_val,
589	                args.window_size_left, args.window_size_right,
590	                !Split ? 1 : args.num_splits,
591	                args.kv_batch_idx,
592	                args.cu_seqlens_q, args.cu_seqlens_k, args.cu_seqlens_k_new,
593	                args.seqused_q, args.seqused_k, args.leftpad_k, args.seqlens_rotary,
594	                args.ptr_S_aux,
595	                args.cp_world_size, args.cp_rank, args.cp_tot_seqused_k};
596	    }
