952	    CUTLASS_DEVICE void
953	    warp_scheduler_barrier_sync() {
954	        if constexpr (UseSchedulerBarrier) {
955	            cutlass::arch::NamedBarrier::sync(2 * cutlass::NumThreadsPerWarpGroup, static_cast<uint32_t>(FwdNamedBarriers::WarpSchedulerWG1) - 1 + flash::canonical_warp_group_idx_nosync() /*id*/);
956	        }
957	    }
958	
959	    CUTLASS_DEVICE void
960	    warp_scheduler_barrier_arrive() {
961	        if constexpr (UseSchedulerBarrier) {
962	            static_assert(NumMmaWarpGroups == 2 || NumMmaWarpGroups == 3);
963	            int const cur_WG = flash::canonical_warp_group_idx_nosync() - 1;
964	            int const next_WG = NumMmaWarpGroups == 2
965	                ? 1 - cur_WG
966	                : (cur_WG < NumMmaWarpGroups - 1 ? cur_WG + 1 : 0);
967	            cutlass::arch::NamedBarrier::arrive(2 * cutlass::NumThreadsPerWarpGroup, static_cast<uint32_t>(FwdNamedBarriers::WarpSchedulerWG1) + next_WG /*id*/);
968	        }
969	    }
970	
971	    CUTLASS_DEVICE void
972	    mma_init() {
973	        int warp_group_idx = flash::canonical_warp_group_idx_nosync();
974	        // Tell producers that smem_q is ready
975	        if (!LargeHeadDimV || warp_group_idx == 1) {
976	            cutlass::arch::NamedBarrier::arrive(NumMmaThreadsQK + (Use_TMA_Q ? cutlass::NumThreadsPerWarp : NumProducerThreads), static_cast<uint32_t>(FwdNamedBarriers::QueryEmpty) /*id*/);
977	        }
978	        if (LargeHeadDimV && warp_group_idx > 1) {
979	            cutlass::arch::NamedBarrier::arrive(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PEmpty) /*id*/);
980	        }
981	        if constexpr (UseSchedulerBarrier) {
982	            // We have NamedBarrier for up to 3 WGs
983	            static_assert(NumMmaWarpGroups == 2 || NumMmaWarpGroups == 3);
984	            // WG1 needs the very first signal to start
985	            if (warp_group_idx == 1) {
986	                cutlass::arch::NamedBarrier::arrive(2 * cutlass::NumThreadsPerWarpGroup, static_cast<uint32_t>(FwdNamedBarriers::WarpSchedulerWG1) /*id*/);
987	            }
988	        }
989	    }
