991	    template <typename SharedStorage, typename FrgTensorO, typename Softmax>
992	    CUTLASS_DEVICE bool
993	    mma(Params const& params,
994	        MainloopPipelineK pipeline_k,
995	        MainloopPipelineV pipeline_v,
996	        PipelineState& smem_pipe_read,
997	        FrgTensorO& tOrO,
998	        Softmax& softmax,
999	        int const thread_idx,
1000	        int &work_idx,
1001	        SeqlenInfo_t const& seqlen_info,
1002	        cute::tuple<int32_t, int32_t, int32_t, int32_t> block_coord,
1003	        SharedStorage& shared_storage
1004	        ) {
1005	        static_assert(is_rmem<FrgTensorO>::value, "O tensor must be rmem resident.");
1006	        static constexpr int kBlockM = get<0>(TileShape_MNK{});
1007	        static constexpr int kBlockN = get<1>(TileShape_MNK{});
1008	
1009	        // can't use auto [m_block, ...] = block_coord since structured binding cannot be captured in lambda
1010	        int const m_block = get<0>(block_coord);
1011	        int const bidh = get<1>(block_coord);
1012	        int const bidb = get<2>(block_coord);
1013	        int const split_idx = get<3>(block_coord);
1014	        int const bidh_kv = !PackGQA ? params.qhead_per_khead_divmod.divide(bidh) : bidh;
1015	        auto [n_block_min, n_block_max, n_offset] = BlockMN_t::get_n_block_min_max(
1016	            seqlen_info, m_block, bidb, split_idx, params.num_splits,
1017	            params.window_size_left, params.window_size_right, params.qhead_per_khead_divmod);
1018	        // It's possible to have n_block_max <= n_block_min. We don't want to load Q or change any barrier
1019	        if constexpr (Is_causal || Is_local || Varlen || Split) {
1020	            if (n_block_max <= n_block_min) { return false; }
1021	        }
1022	
1023	        Tensor sQ = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_q.data()), SmemLayoutQ{});
1024	        Tensor sK = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_k.data()), SmemLayoutK{});
1025	        Tensor sV = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_v.data()), SmemLayoutVtMma{});
1026	        Tensor sP = [&] {
1027	            if constexpr (MmaPV_is_RS) {
1028	                // We might not have smem_p if !MmaPV_is_RS, just use smem_q as a placeholder since we don't use it
1029	                return make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_q.data()), SmemLayoutP{});
1030	            } else {
1031	                return make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_p.data()), SmemLayoutP{});
1032	            }
1033	        }();
1034	        Tensor sScale = [&] {
1035	            if constexpr (LargeHeadDimV) {
1036	                return make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_scale.data()), SmemLayoutScale{});
1037	            } else { // won't be used, just a placeholder
1038	                return make_tensor(make_smem_ptr(static_cast<float*>(nullptr)), SmemLayoutScale{});
1039	            }
1040	        }();
1041	        Tensor sQv = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_qv.data()), SmemLayoutQv{});
1042	        Tensor sVMmaQV = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_v.data()), SmemLayoutVMmaQV{});
1043	
1044	        if constexpr (!MmaQK_is_RS) {
1045	            static_assert(stride<0>(typename TiledMmaQK::ALayout{}) == 0 and
1046	                        stride<0>(typename TiledMmaQK::BLayout{}) == 0 and
1047	                        size<0>(typename TiledMmaQK::ALayout{}) == cutlass::NumThreadsPerWarpGroup and
1048	                        size<0>(typename TiledMmaQK::BLayout{}) == cutlass::NumThreadsPerWarpGroup,
1049	                "Stride of the first mode must be 0 and the size of the mode must be NumThreadsPerWarpGroup");
1050	        }
1051	        static constexpr int MmaWarpGroups = size(TiledMmaPV{}) / cutlass::NumThreadsPerWarpGroup;
1052	        Layout warp_group_thread_layout = make_layout(make_shape(Int<MmaWarpGroups>{}),
1053	                                                      make_stride(Int<cutlass::NumThreadsPerWarpGroup>{}));
1054	
1055	        int warp_group_idx = __shfl_sync(0xFFFFFFFF, thread_idx / cutlass::NumThreadsPerWarpGroup, 0);
1056	        TiledMmaQK tiled_mma_qk;
1057	        TiledMmaPV tiled_mma_pv;
1058	        TiledMmaQV tiled_mma_qv;
1059	        auto wg_mma_qk = tiled_mma_qk.get_slice(warp_group_thread_layout(warp_group_idx));
1060	        auto wg_mma_pv = tiled_mma_pv.get_slice(warp_group_thread_layout(warp_group_idx));
1061	        auto wg_mma_qv = tiled_mma_qv.get_slice(warp_group_thread_layout(warp_group_idx));
1062	
1063	        auto smem_tiled_copy_P = make_tiled_copy_C(SmemCopyAtomP{}, tiled_mma_qk);
1064	        auto smem_thr_copy_P = smem_tiled_copy_P.get_thread_slice(thread_idx);
1065	
1066	        // Allocate "fragments/descriptors"
1067	        Tensor tSrQ = wg_mma_qk.partition_fragment_A(sQ);
1068	        Tensor tSrK = wg_mma_qk.partition_fragment_B(sK);
1069	        Tensor tOrV = wg_mma_pv.partition_fragment_B(sV);
1070	        Tensor tOsP = wg_mma_pv.partition_fragment_A(sP);
1071	        Tensor tSrQv = wg_mma_qv.partition_fragment_A(sQv);
1072	        Tensor tSrV = wg_mma_qv.partition_fragment_B(sVMmaQV);
1073	        Tensor tPsP = smem_thr_copy_P.partition_D(cute::as_position_independent_swizzle_tensor(sP));
1074	
1075	        // For storing scales to smem, only used when LargeHeadDimV
1076	        auto thread_mma_pv = tiled_mma_pv.get_thread_slice(thread_idx);
1077	        Tensor taccOcO = thread_mma_pv.partition_C(cute::make_identity_tensor(select<0, 1>(TileShape_MNK_PV{})));
1078	        Tensor taccOcO_rowcol = make_tensor(taccOcO.data(), flash::convert_layout_acc_rowcol(taccOcO.layout()));
1079	        Tensor taccOcO_row = taccOcO_rowcol(_, _0{});
1080	        auto store_scales = [&](auto& scales, int stage) {
1081	            static_assert(CUTE_STATIC_V(size(scales)) == CUTE_STATIC_V(size(taccOcO_row)));
1082	            #pragma unroll
1083	            for (int mi = 0; mi < size(taccOcO_row); ++mi) {
1084	                if (get<1>(taccOcO_row(_0{})) == 0) {
1085	                    sScale(get<0>(taccOcO_row(mi)), stage) = scales(mi);
1086	                }
1087	            }
1088	        };
1089	
1090	        auto consumer_wait = [](auto& pipeline, auto& smem_pipe_read) {
1091	            auto barrier_token = pipeline.consumer_try_wait(smem_pipe_read);
1092	            pipeline.consumer_wait(smem_pipe_read, barrier_token);
1093	        };
1094	
1095	        int const seqlen_q = seqlen_info.seqlen_q;
1096	        // Compute actual seqlen_k for this mma worktile
1097	        int const seqlen_k = seqlen_info.seqlen_k - n_offset;
1098	        int n_block = n_block_max - 1;
1099	
1100	        // NOTE: sink_token_length is dead code
1101	        // But we subtract n_offset for consistency in mask calculations
1102	        flash::Mask<kBlockM, kBlockN, PackGQA, TiledMmaQK> mask(
1103	            thread_idx, seqlen_q, seqlen_k, params.window_size_left, params.window_size_right, 0 - n_offset /*sink_token_length*/,
1104	            params.qhead_per_khead_divmod,
1105	            params.cp_world_size, params.cp_rank, seqlen_info.tot_seqlen_k
1106	        );
1107	
1108	        float softcap_val = params.softcap_val;
1109	        if constexpr (Has_softcap && Is_FP8) {
1110	            float const q_descale = params.ptr_q_descale == nullptr ? 1.0f : params.ptr_q_descale[bidb * get<0>(params.stride_q_descale) + bidh_kv * get<1>(params.stride_q_descale)];
1111	            float const k_descale = params.ptr_k_descale == nullptr ? 1.0f : params.ptr_k_descale[bidb * get<0>(params.stride_k_descale) + bidh_kv * get<1>(params.stride_k_descale)];
1112	            softcap_val *= q_descale * k_descale;
1113	        }
1114	        // Softcapping needs to happen before masking since if we apply after masking, softcapping
1115	        // can turn -inf to e.g. -50.0, which can affect the attention softmax.
1116	        auto scoremod_premask_fn = [&](auto& tSrS) {
1117	            if constexpr (Has_softcap) { flash::apply_softcap(tSrS, softcap_val); }
1118	        };
1119	
1120	        auto write_P_to_smem = [&](auto& tOrP) {
1121	            if constexpr (LargeHeadDimV) {
1122	                cutlass::arch::NamedBarrier::sync(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PEmpty) /*id*/);
1123	            }
1124	            cute::copy(smem_tiled_copy_P, smem_thr_copy_P.retile_S(tOrP), tPsP);
1125	        };
1126	
1127	        auto arrive_on_P_write_barrier = [&] {
1128	            cutlass::arch::fence_view_async_shared();
1129	            __syncwarp();  // Only need syncwarp since each warp is using its own P values for MmaPV
1130	            if constexpr (LargeHeadDimV) {
1131	                cutlass::arch::NamedBarrier::arrive(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PFull) /*id*/);
1132	            }
1133	        };
1134	
1135	        using TensorT = typename Softmax::TensorT;
1136	        using LayoutT = typename TensorT::layout_type;
1137	        auto finalize_dispatch = [&](TensorT& scores_scale, float const v_descale) {
1138	            if (params.ptr_S_aux && (!Split || (split_idx & 0x0000FFFF) == 0)) {
1139	                Tensor sS_aux = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_s_aux.data()), SmemLayoutSAux{});
1140	                Tensor tSrS_aux = make_tensor_like(scores_scale);
1141	                static_assert(is_static<decltype(layout(tSrS_aux))>::value);
1142	                static_assert(size(tSrS_aux) == size(LayoutT{}));
1143	                if constexpr(!PackGQA) {
1144	                    #pragma unroll
1145	                    for(int mi = 0; mi < size(tSrS_aux); ++mi) {
1146	                        tSrS_aux(mi) = static_cast<float>(sS_aux(bidh));
1147	                    }
1148	                } else {
1149	                    Tensor cS = cute::make_identity_tensor(select<0, 1>(TileShape_MNK{}));
1150	                    auto thread_mma_qk = tiled_mma_qk.get_thread_slice(thread_idx);
1151	                    Tensor tScS = thread_mma_qk.partition_C(cS);
1152	                    Tensor tScS_rowcol = make_tensor(tScS.data(), flash::convert_layout_acc_rowcol</*Transposed=*/false>(tScS.layout()));
1153	                    static_assert(size<0>(tScS_rowcol) == size(tSrS_aux));
1154	                    int const qhead_per_khead = params.qhead_per_khead_divmod.divisor;
1155	                    #pragma unroll
1156	                    for(int mi = 0; mi < size(tSrS_aux); ++mi) {
1157	                        int row = m_block * kBlockM + get<0>(tScS_rowcol(mi, _0{}));
1158	                        int bidh_mi = (row % qhead_per_khead) + bidh_kv * qhead_per_khead;
