1	/******************************************************************************
2	 * Copyright (c) 2024, Jay Shah, Ganesh Bikshandi, Ying Zhang, Vijay Thakkar, Pradeep Ramani, Tri Dao.
3	 ******************************************************************************/
4	
5	#pragma once
6	
7	#include <cmath>
8	
9	#include <cute/tensor.hpp>
10	
11	#include <cutlass/numeric_types.h>
12	
13	#include "utils.h"
14	
15	namespace flash {
16	
17	using namespace cute;
18	
19	////////////////////////////////////////////////////////////////////////////////////////////////////
20	
21	template<bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Operator>
22	__device__ __forceinline__ void thread_reduce_(Tensor<Engine0, Layout0> const &tensor, Tensor<Engine1, Layout1> &summary, Operator &op) {
23	    static_assert(Layout0::rank == 2, "Only support 2D Tensor");
24	    static_assert(Layout1::rank == 1, "Only support 1D Tensor");
25	    CUTE_STATIC_ASSERT_V(size<0>(summary) == size<0>(tensor));
26	    #pragma unroll
27	    for (int ni = 0; ni < size<1>(tensor); ni++) {
28	        #pragma unroll
29	        for (int mi = 0; mi < size<0>(tensor); mi++) {
30	            summary(mi) = zero_init && ni == 0 ? tensor(mi, ni) : op(summary(mi), tensor(mi, ni));
31	        }
32	    }
33	}
34	
35	template<typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Operator>
36	__device__ __forceinline__ void quad_allreduce_(Tensor<Engine0, Layout0> &dst, Tensor<Engine1, Layout1> &src, Operator &op) {
37	    CUTE_STATIC_ASSERT_V(size(dst) == size(src));
38	    #pragma unroll
39	    for (int i = 0; i < size(dst); i++) {
40	        dst(i) = Allreduce<4>::run(src(i), op);
41	    }
42	}
43	
44	template<bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Operator>
45	__device__ __forceinline__ void reduce_(Tensor<Engine0, Layout0> const& tensor, Tensor<Engine1, Layout1> &summary, Operator &op) {
46	    thread_reduce_<zero_init>(tensor, summary, op);
47	    quad_allreduce_(summary, summary, op);
48	}
49	
