1440	                cutlass::arch::NamedBarrier::arrive(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PFull) /*id*/);
1441	            }
1442	            softmax.rescale_o(tOrO, scores_scale);
1443	            if constexpr (Is_FP8 && !V_colmajor) { flash::permute_output_fp8(tOrO); }
1444	            ++smem_pipe_read;
1445	        }
1446	        ++work_idx;
1447	        return true;
1448	    }
