78	template<int THREADS>
79	struct Allreduce {
80	    static_assert(THREADS == 32 || THREADS == 16 || THREADS == 8 || THREADS == 4);
81	    template<typename T, typename Operator>
82	    static __device__ __forceinline__ T run(T x, Operator &op) {
83	        constexpr int OFFSET = THREADS / 2;
84	        x = op(x, __shfl_xor_sync(uint32_t(-1), x, OFFSET));
85	        return Allreduce<OFFSET>::run(x, op);
86	    }
87	};
