225	auto mma_partition_fragment_AB(Mma const& mma, Tensor0 const& tensor0) {
226	    if constexpr (A) {
227	        return mma.partition_fragment_A(tensor0);
228	    } else {
229	        return mma.partition_fragment_B(tensor0);
