234	
235	template <bool zero_init=false, int wg_wait=0, bool SwapAB=false, int M_slice=-1,
236	        typename Tensor0, typename Tensor1, typename Tensor2, typename TiledMma>
237	CUTLASS_DEVICE void gemm(TiledMma& tiled_mma, Tensor0 const& tCrA, Tensor1 const& tCrB, Tensor2& tCrC) {
238	#ifndef FLASHATTENTION_DISABLE_FP8_TWO_LEVEL_ACCUMULATION
239	    static constexpr bool Is_FP8 = cute::is_same_v<typename Tensor0::value_type, cutlass::float_e4m3_t> 
240	        || cute::is_same_v<typename Tensor0::value_type, cutlass::float_e5m2_t>;
241	    static constexpr bool Use_Two_Level = Is_FP8 && !zero_init;
242	    
243	    auto tCrC_original = cute::make_fragment_like(tCrC);
244	    if constexpr (Use_Two_Level) {
245	        // Copy original values to backup
246	        #pragma unroll
247	        for (int i = 0; i < cute::size(tCrC); ++i) {
248	            tCrC_original(i) = tCrC(i);
249	        }
250	        cute::clear(tCrC);
251	    }
252	#endif
253	    if constexpr (M_slice >= 0) {
254	        static constexpr int MMA_M = decltype(size<1>(tCrC))::value;
255	        static_assert(M_slice < MMA_M);
256	        // After logical_divide, C has shape ((2,2,V), (MMA_M, 1), MMA_N)
257	        Tensor tCrC_slice = cute::logical_divide(tCrC, Shape<cute::Underscore, Int<MMA_M>>{})(_, make_coord(Int<M_slice>{}, _), _);
258	        if constexpr (!SwapAB) {
259	            Tensor tCrA_slice = cute::logical_divide(tCrA, Shape<cute::Underscore, Int<MMA_M>>{})(_, make_coord(Int<M_slice>{}, _), _);
260	            gemm<zero_init, wg_wait, SwapAB, /*M_slice=*/-1>(tiled_mma, tCrA_slice, tCrB, tCrC_slice);
261	        } else {
262	            Tensor tCrB_slice = cute::logical_divide(tCrB, Shape<cute::Underscore, Int<MMA_M>>{})(_, make_coord(Int<M_slice>{}, _), _);
263	            gemm<zero_init, wg_wait, SwapAB, /*M_slice=*/-1>(tiled_mma, tCrA, tCrB_slice, tCrC_slice);
264	        }
265	    } else {
266	        constexpr bool Is_RS = !cute::is_base_of<cute::GMMA::DescriptorIterator, typename TiledMma::FrgTypeA>::value;
267	        // Need to cast away const on tCrA since warpgroup_fence_operand doesn't take const
268	        if constexpr (Is_RS) {
269	            if constexpr (!SwapAB) {
270	                warpgroup_fence_operand(const_cast<Tensor0 &>(tCrA));
271	            } else {
272	                warpgroup_fence_operand(const_cast<Tensor1 &>(tCrB));
273	            }
274	        }
275	        warpgroup_fence_operand(tCrC);
276	        warpgroup_arrive();
277	        if constexpr (zero_init) {
278	            tiled_mma.accumulate_ = GMMA::ScaleOut::Zero;
279	        }
280	        static constexpr int kNumKIters = CUTE_STATIC_V(size<2>(tCrA));
281	        static constexpr int kMaxKIters = 16;
282	        // Unroll the K mode manually to set scale D to 1
283	        CUTLASS_PRAGMA_UNROLL
284	        for (int k_block = 0; k_block < std::min(kNumKIters, kMaxKIters); ++k_block) {
285	            if constexpr (!SwapAB) {
286	                cute::gemm(tiled_mma, tCrA(_,_,k_block), tCrB(_,_,k_block), tCrC);
287	            } else {
288	                cute::gemm(tiled_mma, tCrB(_,_,k_block), tCrA(_,_,k_block), tCrC);
289	            }
290	            tiled_mma.accumulate_ = GMMA::ScaleOut::One;
291	        }
292	        // In the case of large kNumKIters, the compiler chooses to store the smem addresses
293	        // in registers, causing spills. This loop forces the compiler to recompute the addresses.
294	        if constexpr (kNumKIters > kMaxKIters) {
295	            // This will always be zero, just a way to force the compiler to recompute the smem
296	            // addresses. This results in USEL instructions. There's probably a better way to do this.
297	            int const k_offset = cutlass::canonical_warp_group_idx() < 128 ? 0 : 1;
298	            CUTLASS_PRAGMA_UNROLL
299	            for (int k_block = kMaxKIters; k_block < kNumKIters; ++k_block) {
300	                if constexpr (!SwapAB) {
301	                    cute::gemm(tiled_mma, tCrA(_,_,k_block + k_offset), tCrB(_,_,k_block + k_offset), tCrC);
302	                } else {
303	                    cute::gemm(tiled_mma, tCrB(_,_,k_block + k_offset), tCrA(_,_,k_block + k_offset), tCrC);
304	                }
305	                tiled_mma.accumulate_ = GMMA::ScaleOut::One;
306	            }
307	        }
308	        warpgroup_commit_batch();
309	        if constexpr (wg_wait >= 0) { warpgroup_wait<wg_wait>(); }
310	        warpgroup_fence_operand(tCrC);
311	        if constexpr (Is_RS) {
312	            if constexpr (!SwapAB) {
313	                warpgroup_fence_operand(const_cast<Tensor0 &>(tCrA));
314	            } else {
315	                warpgroup_fence_operand(const_cast<Tensor1 &>(tCrB));
316	            }
317	        }
318	    }
319	
320	#ifndef FLASHATTENTION_DISABLE_FP8_TWO_LEVEL_ACCUMULATION
321	    if constexpr (Use_Two_Level) {
322	        #pragma unroll
323	        for (int i = 0; i < cute::size(tCrC); ++i) {
324	            tCrC(i) = tCrC_original(i) + tCrC(i);  // Add temp results to original
325	        }
326	    }
327	#endif
328	}
