369	template<typename Tensor0, typename Tensor1, typename Tensor2, typename Tensor3,
370	         typename TiledMma, typename TiledCopy, typename ThrCopy>
371	CUTLASS_DEVICE void gemm_rs_sm80(Tensor0 &acc, Tensor1 &tCrA, Tensor2 &tCrB, Tensor3 const& tCsB,
372	                                 TiledMma tiled_mma, TiledCopy smem_tiled_copy_B,
373	                                 ThrCopy smem_thr_copy_B) {
374	    CUTE_STATIC_ASSERT_V(size<1>(tCrA) == size<1>(acc));                     // MMA_M
375	    CUTE_STATIC_ASSERT_V(size<1>(tCrB) == size<2>(acc));                     // MMA_N
376	    CUTE_STATIC_ASSERT_V(size<2>(tCrA) == size<2>(tCrB));                     // MMA_K
377	    Tensor tCrB_copy_view = smem_thr_copy_B.retile_D(tCrB);
378	    CUTE_STATIC_ASSERT_V(size<1>(tCsB) == size<1>(tCrB_copy_view));            // N
379	    cute::copy(smem_tiled_copy_B, tCsB(_, _, _0{}), tCrB_copy_view(_, _, _0{}));
380	    #pragma unroll
381	    for (int i = 0; i < size<2>(tCrA); ++i) {
382	        if (i < size<2>(tCrA) - 1) {
383	            cute::copy(smem_tiled_copy_B, tCsB(_, _, i + 1), tCrB_copy_view(_, _, i + 1));
384	        }
385	        cute::gemm(tiled_mma, tCrA(_, _, i), tCrB(_, _, i), acc);
386	    }
387	}
