556	template <typename Fragment>
557	CUTLASS_DEVICE void permute_Cregs_fp8(Fragment &frag) {
558	    // frag has shape ((2, 2, N / 8), MMA_M, MMA_N), each element is 32 bits
559	    static_assert(decltype(size<0, 0>(frag))::value == 2);
560	    static_assert(decltype(size<0, 1>(frag))::value == 2);
561	    static_assert(decltype(size<0, 2>(frag))::value % 2 == 0);
562	    static_assert(decltype(stride<0, 0>(frag))::value == 1);
563	    static_assert(sizeof(typename Fragment::value_type) == 4);
564	    Tensor frag_64b = group_modes<1, 3>(recast<uint2>(frag));  // ((1, 2, N / 8), (MMA_M, MMA_N))
565	    #pragma unroll
566	    for (int mi = 0; mi < size<1>(frag_64b); ++mi) {
567	        #pragma unroll
568	        for (int i = 0; i < size<0, 2>(frag_64b) / 2; ++i) {
569	            cutlass::swap(frag_64b(make_coord(_0{}, _1{}, 2 * i), mi), frag_64b(make_coord(_0{}, _0{}, 2 * i + 1), mi));
570	        }
571	    }
572	}
