576	template <typename Fragment>
577	CUTLASS_DEVICE void permute_output_fp8(Fragment &out) {
578	    // out has shape ((2, 2, N / 8), MMA_M, MMA_N), each element is 32 bits
579	    static_assert(decltype(size<0, 0>(out))::value == 2);
580	    static_assert(decltype(size<0, 1>(out))::value == 2);
581	    static_assert(decltype(size<0, 2>(out))::value % 2 == 0);
582	    static_assert(decltype(stride<0, 0>(out))::value == 1);
583	    static_assert(sizeof(typename Fragment::value_type) == 4);
584	    Tensor frag = group_modes<1, 3>(out);  // ((2, 2, N / 8), (MMA_M, MMA_N))
585	    #pragma unroll
586	    for (int mi = 0; mi < size<1>(frag); ++mi) {
587	        #pragma unroll
588	        for (int j = 0; j < size<0, 1>(frag); ++j) {
589	            #pragma unroll
590	            for (int i = 0; i < size<0, 2>(frag) / 2; ++i) {
591	                cutlass::swap(frag(make_coord(_1{}, j, 2 * i), mi), frag(make_coord(_0{}, j, 2 * i + 1), mi));
592	            }
593	        }
594	    }
595	}
