648	template <typename Engine, typename Layout>
649	CUTLASS_DEVICE auto calculate_dtanh(Tensor<Engine, Layout> &tensor){
650	    Tensor out = make_fragment_like<float>(tensor);
651	    #pragma unroll
652	    for (int i = 0; i < size(tensor); ++i) {
653	        out(i) = 1.f - (tensor(i) * tensor(i));
654	    }
655	    return out;
