660	template<class T>
661	CUTE_DEVICE T warp_prefix_sum(T val) {
662	    int lane = threadIdx.x % cutlass::NumThreadsPerWarp;
663	    CUTLASS_PRAGMA_UNROLL
664	    for (int i = 1; i < cutlass::NumThreadsPerWarp; i <<= 1) {
665	        T partial_sum = __shfl_up_sync(0xffffffff, val, i);
666	        if (lane >= i) { val += partial_sum; }
667	    }
668	    return val;
669	}
670	
671	////////////////////////////////////////////////////////////////////////////////////////////////////
672	
673	template<typename T>
674	CUTE_DEVICE T warp_shfl_get(T val, int src_lane) {
675	    return __shfl_sync(0xffffffff, val, src_lane);
676	};
677	
678	template<typename T>
679	CUTE_DEVICE T warp_shfl_get_last(T val) {
680	    return __shfl_sync(0xffffffff, val, cutlass::NumThreadsPerWarp - 1);
681	};
682	
683	CUTE_DEVICE int warp_last_true_laneid(bool cond) {
684	    return __popc(__ballot_sync(0xffffffff, cond));
685	};
686	
687	////////////////////////////////////////////////////////////////////////////////////////////////////
688	
689	template<class T>
690	CUTE_DEVICE T warp_uniform(T a) {
691	    return __shfl_sync(0xffffffff, a, 0);
692	}
693	
694	////////////////////////////////////////////////////////////////////////////////////////////////////
695	
696	CUTLASS_DEVICE
697	int canonical_warp_group_idx_nosync() {
698	    return threadIdx.x / cutlass::NumThreadsPerWarpGroup;
699	}
700	
701	////////////////////////////////////////////////////////////////////////////////////////////////////
